package com.shsc.agents.auth;

import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.PublicKey;
import java.security.Signature;
import java.security.spec.X509EncodedKeySpec;
import java.text.ParseException;
import java.util.Base64;

import com.nimbusds.jose.JWSAlgorithm;
import com.nimbusds.jwt.JWTClaimsSet;
import com.nimbusds.jwt.SignedJWT;

/**
 * Ed25519 helpers based on the JDK provider (no extra dependency): raw 32-byte public keys
 * (as generated by Go {@code crypto/ed25519}) and verification of compact JWS ("EdDSA").
 */
final class Ed25519 {

    /** DER prefix of an X.509 SubjectPublicKeyInfo for Ed25519 (OID 1.3.101.112). */
    private static final byte[] X509_PREFIX = {0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x03, 0x21, 0x00};

    private Ed25519() {
    }

    /** Decodes a base64url raw public key; throws IllegalArgumentException if not a valid key. */
    static byte[] decodePublicKey(String base64Url) {
        byte[] raw;
        try {
            raw = Base64.getUrlDecoder().decode(base64Url.trim());
        } catch (IllegalArgumentException e) {
            throw new IllegalArgumentException("public key is not base64url");
        }
        if (raw.length != 32) {
            throw new IllegalArgumentException("Ed25519 public key must be 32 bytes");
        }
        toPublicKey(raw);
        return raw;
    }

    static PublicKey toPublicKey(byte[] raw) {
        byte[] der = new byte[X509_PREFIX.length + raw.length];
        System.arraycopy(X509_PREFIX, 0, der, 0, X509_PREFIX.length);
        System.arraycopy(raw, 0, der, X509_PREFIX.length, raw.length);
        try {
            return KeyFactory.getInstance("Ed25519").generatePublic(new X509EncodedKeySpec(der));
        } catch (GeneralSecurityException e) {
            throw new IllegalArgumentException("invalid Ed25519 public key", e);
        }
    }

    /** Parsed, still unverified assertion. */
    record Assertion(SignedJWT jws, JWTClaimsSet claims) {

        static Assertion parse(String compact) {
            try {
                SignedJWT jws = SignedJWT.parse(compact);
                JWSAlgorithm alg = jws.getHeader().getAlgorithm();
                if (!JWSAlgorithm.EdDSA.equals(alg) && !JWSAlgorithm.Ed25519.equals(alg)) {
                    throw new IllegalArgumentException("unsupported algorithm");
                }
                return new Assertion(jws, jws.getJWTClaimsSet());
            } catch (ParseException e) {
                throw new IllegalArgumentException("malformed assertion");
            }
        }

        boolean verify(byte[] rawPublicKey) {
            try {
                Signature verifier = Signature.getInstance("Ed25519");
                verifier.initVerify(toPublicKey(rawPublicKey));
                verifier.update(jws.getSigningInput());
                return verifier.verify(jws.getSignature().decode());
            } catch (GeneralSecurityException | IllegalArgumentException e) {
                return false;
            }
        }
    }
}
